import { Bar, BarChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { CalendarDays } from 'lucide-react';
import ridesByDay from '@/data/rides_by_day.json';
import type { RidesByDay } from '@/types/charts';
import { axisTick, formatRideTick, tooltipStyle } from './chartTheme';

/**
 * Rides by day of week — train.ipynb cell 5 (`df.day_of_week.value_counts()`), generated by
 * scripts/generate_chart_data.py. Answers the case study's "busiest day of week" question.
 */
export function RidesByDayChart() {
  const data = ridesByDay as RidesByDay[];

  return (
    <Card className="rounded-lg border">
      <CardHeader className="flex-row items-center gap-2 space-y-0 pb-3">
        <CalendarDays className="h-5 w-5 text-muted-foreground" />
        <div>
          <CardTitle className="text-lg font-semibold">Rides by Day of Week</CardTitle>
          <CardDescription className="text-sm">Busiest day of the week</CardDescription>
        </div>
      </CardHeader>
      <CardContent>
        <ResponsiveContainer width="100%" height={240}>
          <BarChart data={data} margin={{ top: 10, right: 10, left: 10, bottom: 0 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="var(--border)" vertical={false} />
            <XAxis dataKey="day" tick={axisTick} axisLine={false} tickLine={false} />
            <YAxis
              tick={axisTick}
              axisLine={false}
              tickLine={false}
              tickFormatter={formatRideTick}
            />
            <Tooltip
              cursor={{ fill: 'var(--accent)' }}
              contentStyle={tooltipStyle}
              formatter={(value) => [
                typeof value === 'number' ? value.toLocaleString() : String(value),
                'Rides',
              ]}
            />
            <Bar dataKey="rides" fill="var(--chart-1)" radius={[4, 4, 0, 0]} maxBarSize={48} />
          </BarChart>
        </ResponsiveContainer>
      </CardContent>
    </Card>
  );
}
